// AI selects a tool; application guards and customer approval remain in control.
const aiPanel=document.createElement('section');aiPanel.className='card';
aiPanel.innerHTML='<h2>Bonus · AI thật qua OpenProvider</h2><p>Chỉ dùng tin khách dựng trong lab. AI chọn tool; không có giao dịch hãng bay thật.</p><form id="realAI"><label for="realText">Tin khách</label><textarea id="realText" rows="3" maxlength="2000" required style="width:100%;font:inherit">Hoàn vé cho bé Bình thôi, tôi vẫn bay.</textarea><button type="submit" class="btn pri">Gọi AI chọn tool</button></form><pre id="realResult" style="white-space:pre-wrap;overflow-wrap:anywhere" role="status" aria-live="polite"></pre><div id="realAction"></div>';
document.querySelector('aside').prepend(aiPanel);
document.querySelector('#realAI').onsubmit=async event=>{event.preventDefault();const submit=event.target.querySelector('button'),out=document.querySelector('#realResult'),actions=document.querySelector('#realAction');submit.disabled=true;actions.replaceChildren();out.textContent='Đang gọi AI thật; chưa đổi vé hoặc gửi hoàn…';
try{if(location.protocol==='file:')throw Error('Cần chạy node --env-file=.env prototype/server.mjs và mở http://localhost:8055');
const response=await fetch('/api/decide',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:document.querySelector('#realText').value})});const data=await response.json();if(!response.ok)throw Error(data.error);
out.textContent=`Model: ${data.model}\nResponse ID: ${data.response_id}\nTool AI chọn: ${data.selected_tool}\nLý do: ${data.reason}\nAI nói: ${data.reply}\nLuật ứng dụng: ${data.policy}\nLog: prototype/ai-evidence.jsonl`;
const button=document.createElement('button');button.className='btn';button.textContent='Tiếp tục theo quyền ứng dụng';button.onclick=async()=>{button.disabled=true;try{if(['chuyen_nhan_vien','gui_yeu_cau_hoan_ve'].includes(data.selected_tool))await handoff('AI thật đề xuất '+data.selected_tool+'; cần nhân viên xác minh', 'AI chỉ đề xuất; chưa có yêu cầu hoàn nào được gửi.');else await listFlights('AI đã đề xuất '+data.selected_tool+'. Bạn cần chọn chuyến cụ thể; chỉ đổi sau bước duyệt.');}finally{button.disabled=false;}};actions.append(button);
}catch(error){out.textContent=error.message||'Không gọi được AI; chưa thực hiện thao tác.';}finally{submit.disabled=false;}};
